package id.kemkes.satusehat;
import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.*;
final class FhirClient {private final SatusehatConfig c;private final HttpClient http;private final TokenProvider tokens;FhirClient(SatusehatConfig c,HttpClient h,TokenProvider t){this.c=c;http=h;tokens=t;}FhirResponse requestOnce(String method,String rt,String id,String payload) throws Exception{String u=c.fhirBaseUrl()+"/"+rt+(id==null||id.isBlank()?"":"/"+id);String m=method.toUpperCase();var b=HttpRequest.newBuilder(URI.create(u)).timeout(Duration.ofSeconds(c.timeoutSeconds())).header("Authorization","Bearer "+tokens.get()).header("Accept","application/fhir+json, application/json").header("Content-Type",m.equals("PATCH")?"application/json":"application/fhir+json");HttpRequest.BodyPublisher bp=payload==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(payload);var req=b.method(m,bp).build();var r=http.send(req,HttpResponse.BodyHandlers.ofString());Map<String,String> hs=new HashMap<>();r.headers().map().forEach((k,v)->{if(!v.isEmpty())hs.put(k,v.getFirst());});return new FhirResponse(r.statusCode(),r.body(),hs);}}
